('6ca711f5-a257-4533-9bc3-2c12a21601c2', '6aeb0155-596e-42fe-8952-378b52dacdf7', 'Saúde e bem-estar', 'Clínicas, salões de beleza, barbearias e academias que precisam de cartão de visita, agenda e material de fidelização.', ARRAY['PR'], ARRAY['Curitiba','Araucária','Campo Largo'], ARRAY['Curitiba e Região Metropolitana'], ARRAY['Clínica','Salão de beleza','Barbearia','Academia','Clínica veterinária'], ARRAY['pequeno','médio'], 1, 25, 'até R$ 30 mil/mês', ARRAY['cartão fidelidade','agenda personalizada','banner','identidade visual'], true),
