insert into public.knowledge_entries (id, company_id, title, category, content, tags, is_active, created_by) values
('b0000000-0000-4000-8000-000000000001', '6aeb0155-596e-42fe-8952-378b52dacdf7', 'Sobre a LumiLife Gráfica', 'geral', 'A LumiLife Gráfica é uma gráfica rápida e de comunicação visual localizada em Curitiba/PR, especializada em impressos personalizados, brindes corporativos e sinalização. Atendemos pequenos e médios negócios em toda a Região Metropolitana de Curitiba com prazos ágeis e atendimento consultivo.', ARRAY['institucional','sobre'], true, '5f72bb0f-326c-4c32-83f0-2a78a62c314f'),
('b0000000-0000-4000-8000-000000000002', '6aeb0155-596e-42fe-8952-378b52dacdf7', 'Catálogo de produtos', 'produtos', 'Nosso catálogo cobre impressos (cartão de visita, banner, cardápio, panfleto, folder), personalizados têxteis (camiseta, DTF), brindes corporativos (canecas, agendas, kits), sinalização (placas em PVC, faixas, adesivos) e itens de identidade visual (etiquetas, rótulos, tags, sacolas).', ARRAY['produtos','catálogo'], true, '5f72bb0f-326c-4c32-83f0-2a78a62c314f'),
('b0000000-0000-4000-8000-000000000003', '6aeb0155-596e-42fe-8952-378b52dacdf7', 'Política de preços e negociação', 'preços', 'Os valores variam conforme quantidade, material e acabamento. Para pedidos acima de 500 unidades, aplicamos desconto progressivo. Orçamentos com prazo maior que 10 dias úteis costumam ter valor mais competitivo. Sempre apresentar faixa de preço inicial e condicionar valor final à especificação completa.', ARRAY['preços','negociação','desconto'], true, '5f72bb0f-326c-4c32-83f0-2a78a62c314f'),
('b0000000-0000-4000-8000-000000000004', '6aeb0155-596e-42fe-8952-378b52dacdf7', 'Materiais e acabamentos disponíveis', 'materiais e acabamentos', 'Trabalhamos com papel couché, papel reciclado, vinil adesivo, lona banner, PVC 3mm/5mm, tecido 100% algodão e poliéster para DTF. Acabamentos: laminação fosca/brilho, verniz UV localizado, corte especial e acabamento com ilhós em faixas e banners.', ARRAY['materiais','acabamentos'], true, '5f72bb0f-326c-4c32-83f0-2a78a62c314f'),
('b0000000-0000-4000-8000-000000000005', '6aeb0155-596e-42fe-8952-378b52dacdf7', 'Prazos de produção', 'prazos', 'Itens de papelaria simples (cartão de visita, panfleto): 2-3 dias úteis. Banners e placas: 3-5 dias úteis. Camisetas e produtos têxteis com DTF: 4-6 dias úteis. Brindes corporativos com personalização: 7-10 dias úteis, conforme quantidade e disponibilidade de estoque do brinde base.', ARRAY['prazos','produção'], true, '5f72bb0f-326c-4c32-83f0-2a78a62c314f'),
('b0000000-0000-4000-8000-000000000006', '6aeb0155-596e-42fe-8952-378b52dacdf7', 'Regiões atendidas', 'regiões atendidas', 'Atendemos Curitiba e Região Metropolitana: São José dos Pinhais, Colombo, Pinhais, Araucária, Campo Largo, Quatro Barras e Piraquara. Entrega própria para pedidos acima de R$ 300 dentro de Curitiba; demais regiões via transportadora parceira.', ARRAY['entrega','regiões','logística'], true, '5f72bb0f-326c-4c32-83f0-2a78a62c314f'),
('b0000000-0000-4000-8000-000000000007', '6aeb0155-596e-42fe-8952-378b52dacdf7', 'Diferenciais competitivos', 'diferenciais', 'Atendimento consultivo com recomendação de produtos por segmento, prazos ágeis, portfólio amplo em um único fornecedor (impressos + têxtil + brindes + sinalização), e possibilidade de amostra física antes do fechamento para pedidos grandes.', ARRAY['diferenciais','vendas'], true, '5f72bb0f-326c-4c32-83f0-2a78a62c314f'),
('b0000000-0000-4000-8000-000000000008', '6aeb0155-596e-42fe-8952-378b52dacdf7', 'Perguntas frequentes de clientes', 'perguntas frequentes', 'P: Vocês fazem entrega? R: Sim, entrega própria em Curitiba e transportadora parceira na região metropolitana. P: Tem valor mínimo de pedido? R: Não, mas pedidos maiores têm desconto progressivo. P: Posso ver uma amostra antes? R: Sim, para pedidos acima de 200 unidades enviamos amostra física ou digital.', ARRAY['faq','atendimento'], true, '5f72bb0f-326c-4c32-83f0-2a78a62c314f')
insert into public.message_templates (id, company_id, name, channel, subject, preheader, body, cta, is_ai_generated, created_by) values
('c0000000-0000-4000-8000-000000000001', '6aeb0155-596e-42fe-8952-378b52dacdf7', 'Primeiro contato - WhatsApp', 'whatsapp', null, null, 'Olá! Tudo bem? Conheci o trabalho de vocês e acredito que a LumiLife Gráfica pode ajudar com material personalizado. Posso te apresentar algumas opções?', 'Responder e agendar conversa', true, '5f72bb0f-326c-4c32-83f0-2a78a62c314f'),
('c0000000-0000-4000-8000-000000000002', '6aeb0155-596e-42fe-8952-378b52dacdf7', 'Primeiro contato - Email', 'email', 'Material personalizado para o seu negócio', 'A LumiLife Gráfica pode ajudar sua empresa', 'Olá! Tudo bem? Conheci o trabalho de vocês e acredito que a LumiLife Gráfica pode ajudar com material personalizado. Posso te apresentar algumas opções?', 'Agendar apresentação', true, '5f72bb0f-326c-4c32-83f0-2a78a62c314f'),
('c0000000-0000-4000-8000-000000000003', '6aeb0155-596e-42fe-8952-378b52dacdf7', 'Envio de orçamento', 'whatsapp', null, null, 'Segue nosso orçamento: R$ {{valor}} para o pedido combinado, com prazo de produção de alguns dias úteis. Fico à disposição!', 'Confirmar pedido', false, '5f72bb0f-326c-4c32-83f0-2a78a62c314f'),
('c0000000-0000-4000-8000-000000000004', '6aeb0155-596e-42fe-8952-378b52dacdf7', 'Follow-up sem resposta', 'whatsapp', null, null, 'Oi! Passando para saber se conseguiu ver nossa proposta. Fico à disposição para tirar dúvidas ou ajustar o orçamento conforme sua necessidade.', 'Reengajar lead', true, '5f72bb0f-326c-4c32-83f0-2a78a62c314f')
